                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE as select Branch_Code, Branch_Name, BRANCH_SHORT_NAME, bill_no, new_bill_no, retail_cust_mobile_no, retail_cust_name, retail_cust_email_id, LSTITEMS, bill_cancelled, bill_date, Bill_Time, ListCreditCard, Doc_Prefix, Account_Name from ( select _airbyte_Data:Branch_Code::varchar Branch_Code, _airbyte_Data:Branch_Name::varchar Branch_Name, _airbyte_Data:Branch_Short_Name::varchar BRANCH_SHORT_NAME, _airbyte_data:Vouch_Code::varchar bill_no, CASE WHEN _airbyte_Data:Doc_Prefix::varchar = \'OMS\' THEN CONCAT(_airbyte_Data:Branch_Code, _airbyte_Data:Bill_no::varchar) ELSE _airbyte_Data:New_Bill_No::varchar END AS new_bill_no, _airbyte_Data:Retail_Cust_Mobile_No::varchar retail_cust_mobile_no, _airbyte_Data:Retail_Cust_Name::varchar retail_cust_name, _airbyte_Data:Retail_Cust_Email_Id::varchar retail_cust_email_id, _airbyte_Data:LstItems LSTITEMS, _airbyte_Data:ListCreditCard ListCreditCard, _airbyte_Data:Bill_Cancelled::varchar bill_cancelled, _airbyte_Data:Bill_Date::varchar bill_date, _airbyte_Data:Bill_Time::varchar Bill_Time, _airbyte_Data:Doc_Prefix::varchar Doc_Prefix, _airbyte_Data:Account_Name::varchar Account_Name, row_number() over(partition by _airbyte_data:Vouch_Code::varchar order by _airbyte_emitted_at desc) rw from snitch_db.maplemonk._airbyte_raw_LOGICERP_FY2324_GET_SALE_INVOICE) where rw=1 and to_date(bill_date,\'DD/MM/YYYY\') < \'2024-04-01\' and new_bill_no not in (select distinct new_bill_no FROM SNITCH_DB.MAPLEMONK.logicerpnew_get_sale_invoice where to_date(bill_date,\'DD/MM/YYYY\') >= \'2024-04-01\') union all select Branch_Code, Branch_Name, BRANCH_SHORT_NAME, bill_no, new_bill_no, retail_cust_mobile_no, retail_cust_name, retail_cust_email_id, LSTITEMS, bill_cancelled, bill_date, Bill_Time, ListCreditCard, Doc_Prefix, Account_Name from ( select _airbyte_Data:Branch_Code::varchar Branch_Code, _airbyte_Data:Branch_Name::varchar Branch_Name, _airbyte_Data:Branch_Short_Name::varchar BRANCH_SHORT_NAME, _airbyte_data:Vouch_Code::varchar bill_no, CASE WHEN _airbyte_Data:Doc_Prefix::varchar = \'OMS\' THEN CONCAT(_airbyte_Data:Branch_Code, _airbyte_Data:Bill_no::varchar) ELSE _airbyte_Data:New_Bill_No::varchar END AS new_bill_no, _airbyte_Data:Retail_Cust_Mobile_No::varchar retail_cust_mobile_no, _airbyte_Data:Retail_Cust_Name::varchar retail_cust_name, _airbyte_Data:Retail_Cust_Email_Id::varchar retail_cust_email_id, _airbyte_Data:LstItems LSTITEMS, _airbyte_Data:ListCreditCard ListCreditCard, _airbyte_Data:Bill_Cancelled::varchar bill_cancelled, _airbyte_Data:Bill_Date::varchar bill_date, _airbyte_Data:Bill_Time::varchar Bill_Time, _airbyte_Data:Doc_Prefix::varchar Doc_Prefix, _airbyte_Data:Account_Name::varchar Account_Name, row_number() over(partition by (CASE WHEN _airbyte_Data:Doc_Prefix::varchar = \'OMS\' THEN _airbyte_Data:Order_No::varchar ELSE _airbyte_Data:New_Bill_No::varchar END) order by _airbyte_emitted_at desc) rw from snitch_db.maplemonk._AIRBYTE_RAW_LOGICERPNEW_GET_SALE_INVOICE ) where rw=1 and to_date(bill_date,\'DD/MM/YYYY\') >= \'2024-04-01\'; Create or Replace TABLE sNITCH_DB.MAPLEMONK.STORE_fact_items_offline as select cd.CardName upi_payment, cash.payment as cach_payment, oth.CardName as other_payment, cardedc.CardName as edc_payment, card.CardName as card_payment, o.*, coalesce(e.product_name, o.product_name) producT_name_shopify, null pla_spends, null banner_spends, null sales_target, null spends_target, uam.CATEGORY as Category_merge, uam.sleeve_type, uam.collar_type, uam.FABRIC, uam.hem, uam.design, uam.closure, uam.fit, uam.occassion, uam.color, am.sku_class, am.category_class from ( select Branch_Code::varchar as Branch_Code, Branch_Name::varchar as marketplace, Branch_Name::varchar as marketplace_mapped, BRANCH_SHORT_NAME::varchar as source, bill_no::varchar as order_id, new_bill_no::varchar as ordeR_name, Doc_Prefix, Account_Name, RIGHT(REGEXP_REPLACE(retail_cust_mobile_no, \'[^a-zA-Z0-9]+\', \'\'), 10) phone, retail_cust_name::varchar as name, retail_cust_email_id::varchar as email, null as SHIPPING_LAST_UPDATE_DATE, null as SHIPPING_LAST_UPDATE_timestamp, replace(A.Value:AddlItemCode,\'\"\',\'\')::varchar as sku, SPLIT_PART(sku, \'-\', -1) AS Size, CASE WHEN upper(sku) LIKE \'4C%\' THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) || \'-\' || SPLIT_PART(sku, \'-\', 3) WHEN POSITION(\'-\' IN sku) > 0 THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) ELSE sku END AS sku_group, replace(A.Value:HSN_Code::varchar,\'\"\',\'\') as product_id, null as product_name, \'INR\' as currency, null as address_line1, null as address_line2, null as city, null as state, null as country, null as pincode, case when lower(bill_cancelled) = \'false\' then \'Processed\' else \'Cancelled\' end as ORDER_STATUS, to_date(bill_date, \'DD/MM/YYYY\') as order_date, TRY_TO_TIMESTAMP(bill_time, \'DD/MM/YYYY HH12:MI AM\') order_timestamp , null as shipping_price, A.Value:Quantity::int as SUBORDER_QUANTITY, CASE WHEN A.Value:Lot_SP_Rate2 =0 THEN A.Value:Lot_Basic_Rate ::int ELSE A.Value:Lot_SP_Rate2 END AS COGS_PRICE, A.Value:Quantity::int as shipping_quantity, (A.Value:CD::float)*-1 as discount, (A.Value:Tax_Amt_1::float) + (A.Value:Tax_Amt_3::float) as tax, A.Value:Net_Amt::varchar as SELLING_PRICE, null as shippingPackageCode, null as shippingPackageStatus, replace(A.Value:Godown_Name::varchar,\'\"\',\'\') as warehouse_name, replace(A.Value:SO_Item_Order_ID::varchar,\'\"\',\'\') as saleOrderItemCode, replace(A.Value:Item_MRP::varchar,\'\"\',\'\') as MRP, replace(A.Value:SO_Item_Order_ID::varchar,\'\"\',\'\') as SALES_ORDER_ITEM_ID, null as courier, null as shipping_courier, null as shipping_status, null as created_timestamp, null as picking_timestamp, null as picked_timestamp, null as packed_timestamp, null as manifested_timestamp, null as dispatched_timestamp, to_date(bill_date, \'DD/MM/YYYY\') Dispatch_date, to_date(bill_date, \'DD/MM/YYYY\') Delivered_Date, null as delivered_timestamp, null Return_Date, 0 as days_to_dispatch, null as awb, null as return_flag, null as return_quantity, case when order_status = \'CANCELLED\' then suborder_quantity else 0 end::int as cancelled_quantity, case when dense_rank()over(partition by phone,order_date order by order_date asc) = 1 then \'New\' else \'Repeat\' end as new_customer_flag, FIRST_VALUE(product_name) OVER ( PARTITION BY phone ORDER BY order_date asc ) AS acquisition_product, 0 as days_in_shipment, 0 as dispatch_to_delivery_days, null as invoice_date, null as cost, CASE WHEN replace(A.Value:Item_Group_Name_1::varchar,\'\"\',\'\') = \'\' THEN \'NA\' WHEN lower(replace(A.Value:Item_Group_Name_1::varchar,\'\"\',\'\')) = \'jeans\' THEN \'Denim\' WHEN lower(replace(A.Value:Item_Group_Name_1::varchar,\'\"\',\'\')) = \'pant\' then \'Pants\' ELSE replace(A.Value:Item_Group_Name_1::varchar,\'\"\',\'\') END AS category from snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE, LATERAL FLATTEN (INPUT => LSTITEMS,outer =>true)A ) o left join ( select * from ( select replace(b.value:\"sku\",\'\"\',\'\') as SKU, title product_name, product_type, row_number() over (partition by sku order by product_name) rw from snitch_db.MAPLEMONK.SHOPIFY_ALL_PRODUCTS, lateral flatten (INPUT => variants,outer => true)b ) where rw = 1 ) e on lower(o.sku) = lower(e.sku) left join ( select distinct new_bill_no, replace(B.Value:CardName::varchar,\'\"\',\'\') as CardName from snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE,LATERAL FLATTEN (INPUT =>ListCreditCard ,outer =>true)B where upper(CardName) in (\'UPI\') )cd on o.ordeR_name::varchar = cd.new_bill_no::varchar left join ( select distinct new_bill_no, replace(B.Value:CardName::varchar,\'\"\',\'\') as CardName from snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE,LATERAL FLATTEN (INPUT =>ListCreditCard ,outer =>true)B where upper(CardName) in (\'CARD\') )card on o.ordeR_name::varchar = card.new_bill_no::varchar left join ( select distinct new_bill_no, replace(B.Value:CardName::varchar,\'\"\',\'\') as CardName from snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE,LATERAL FLATTEN (INPUT =>ListCreditCard ,outer =>true)B where upper(CardName) in (\'EDC\') )cardedc on o.ordeR_name::varchar = cardedc.new_bill_no::varchar left join ( select distinct new_bill_no, replace(B.Value:CardName::varchar,\'\"\',\'\') as CardName from snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE,LATERAL FLATTEN (INPUT =>ListCreditCard ,outer =>true)B where upper(CardName) is not null and upper(CardName) not in (\'CARD\',\'UPI\',\'EDC\') )oth on o.ordeR_name::varchar = oth.new_bill_no::varchar left join ( select distinct new_bill_no, replace(B.Value:CardName::varchar,\'\"\',\'\') as CardName, \'CASH\' as payment from snitch_db.maplemonk.LOGICERPConsolidated_GET_SALE_INVOICE,LATERAL FLATTEN (INPUT =>ListCreditCard ,outer =>true)B where upper(CardName) is null )cash on o.ordeR_name::varchar = cash.new_bill_no::varchar left join ( SELECT * FROM ( select distinct CASE WHEN UPPER(sku_group) LIKE \'4C%\' THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) || \'-\' || SPLIT_PART(sku_group, \'-\', 3) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END AS sku_group, new_category as CATEGORY, sleeve_type, collar_new as collar_type, material_new as FABRIC, null hem, designs as design, null closure, fit, occassion_new as occassion, color, ROW_NUMBER() OVER (PARTITION BY CASE WHEN UPPER(sku_group) LIKE \'4C%\' THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) || \'-\' || SPLIT_PART(sku_group, \'-\', 3) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END ORDER BY 1) AS RN from snitch_db.maplemonk.unicommerce_availability_merge ) WHERE RN=1 ) uam on o.sku_group = uam.sku_group left join ( SELECT * FROM ( select distinct CASE WHEN UPPER(sku_group) LIKE \'4C%\' THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) || \'-\' || SPLIT_PART(sku_group, \'-\', 3) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END AS sku_group , sku_class, category as category_class, ROW_NUMBER() OVER (PARTITION BY CASE WHEN UPPER(sku_group) LIKE \'4C%\' THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) || \'-\' || SPLIT_PART(sku_group, \'-\', 3) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END ORDER BY 1) RN from snitch_db.maplemonk.availability_master_v2 ) WHERE RN=1 ) am on o.sku_group = am.sku_group ; create or replace table snitch_db.maplemonk.offline_hourly_sales_eoss as WITH current_cutoff AS ( SELECT DATE_TRUNC(\'day\', CURRENT_TIMESTAMP)::TIMESTAMP_NTZ AS today_date, CURRENT_TIMESTAMP::TIMESTAMP_NTZ AS cutoff_time ), eoss_skus AS ( SELECT DISTINCT UPPER(sku_group) AS sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_EOSS WHERE sku_status = \'EOSS\' ), store_info AS ( SELECT DISTINCT branch_code, state, UPPER(am) AS am FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), sales AS ( SELECT si.state, si.am, s.marketplace_mapped AS store, s.branch_code, COALESCE(SUM(CASE WHEN e.sku_group IS NULL THEN s.selling_price ELSE 0 END), 0) AS normal_sales, COALESCE(SUM(CASE WHEN e.sku_group IS NOT NULL THEN s.selling_price ELSE 0 END), 0) AS eoss_sales, COALESCE(SUM(CASE WHEN e.sku_group IS NULL THEN s.mrp * s.suborder_quantity ELSE 0 END), 0) AS normal_mrp, COALESCE(SUM(CASE WHEN e.sku_group IS NOT NULL THEN s.mrp * s.suborder_quantity ELSE 0 END), 0) AS eoss_mrp, COUNT(DISTINCT s.order_id) AS today_bills, COALESCE( SUM( CASE WHEN s.sku_group NOT LIKE \'CB%\' THEN s.shipping_quantity ELSE 0 END ), 0 ) AS today_units FROM SNITCH_DB.MAPLEMONK.STORE_fact_items_offline s JOIN current_cutoff c ON s.order_timestamp >= c.today_date AND s.order_timestamp < c.cutoff_time LEFT JOIN eoss_skus e ON UPPER(s.sku_group) = e.sku_group LEFT JOIN store_info si ON si.branch_code = s.branch_code WHERE LOWER(s.order_status) LIKE \'%process%\' AND s.doc_prefix NOT IN (\'OMS\',\'QCOM\') AND s.marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\', \'SNITCH - WH - SR\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - B2B\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - SNITCH X\' ) GROUP BY si.state, si.am, s.marketplace_mapped, s.branch_code ), returns AS ( SELECT si.state, si.am, r.marketplace_mapped AS store, COALESCE(SUM(CASE WHEN e.sku_group IS NULL THEN r.selling_price ELSE 0 END), 0) AS normal_returns, COALESCE(SUM(CASE WHEN e.sku_group IS NOT NULL THEN r.selling_price ELSE 0 END), 0) AS eoss_returns FROM SNITCH_DB.MAPLEMONK.store_returns_fact_items r JOIN current_cutoff c ON r.order_timestamp >= c.today_date AND r.order_timestamp < c.cutoff_time LEFT JOIN eoss_skus e ON UPPER(r.sku_group) = e.sku_group LEFT JOIN store_info si ON si.branch_code = r.branch_code GROUP BY si.state, si.am, r.marketplace_mapped ), targets AS ( SELECT COALESCE( TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\') ) AS date, REPLACE(\"Target \", \',\', \'\')::INT AS day_target, \"Branch \" AS branch_code FROM SNITCH_DB.MAPLEMONK.MTD_TARGET ) SELECT s.state, s.am, s.store, ROUND(s.normal_sales - COALESCE(r.normal_returns, 0), 0) AS net_normal_sales, ROUND(s.eoss_sales - COALESCE(r.eoss_returns, 0), 0) AS net_eoss_sales, ROUND( (s.normal_sales + s.eoss_sales) - COALESCE(r.normal_returns, 0) - COALESCE(r.eoss_returns, 0), 0 ) AS net_sales, CASE WHEN s.today_bills = 0 THEN 0 ELSE ROUND(s.today_units / s.today_bills, 2) END AS today_upt, CASE WHEN COALESCE(t.day_target, 0) = 0 THEN 0 ELSE ROUND( ( (s.normal_sales + s.eoss_sales) - COALESCE(r.normal_returns, 0) - COALESCE(r.eoss_returns, 0) ) / t.day_target * 100, 2 ) END AS daily_achievement_pct, CASE WHEN s.normal_mrp = 0 THEN 0 ELSE ROUND((s.normal_mrp - s.normal_sales) / s.normal_mrp * 100, 2) END AS normal_discount_pct, CASE WHEN s.eoss_mrp = 0 THEN 0 ELSE ROUND((s.eoss_mrp - s.eoss_sales) / s.eoss_mrp * 100, 2) END AS eoss_discount_pct FROM sales s LEFT JOIN returns r ON s.state = r.state AND s.am = r.am AND s.store = r.store LEFT JOIN targets t ON s.branch_code = t.branch_code AND t.date = CURRENT_DATE ORDER BY net_sales desc, s.state, s.am, s.store ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            